package com.indiesoundquest.tournament.repository; import com.indiesoundquest.tournament.domain.Recording; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; public interface RecordingRepository extends JpaRepository<Recording,UUID>{ List<Recording> findByArtistIdOrderBySeedRankAsc(UUID artistId); @Query("select r from Recording r join fetch r.artist where r.artist.id in :artistIds order by r.seedRank") List<Recording> findByArtistIdInOrderBySeedRankAsc(List<UUID> artistIds); }
